(window.QDATA=window.QDATA||{})[27]={"s":27,"ar":"النمل","tl":"An-Naml","n":93,"place":"makkah","bism":true,"mean":{"en":"The Ant","ur":"چیونٹی","hi":"चींटी"},"v":[{"a":1,"ar":" طسٓ ۚ تِلْكَ ءَايَـٰتُ ٱلْقُرْءَانِ وَكِتَابٍ مُّبِينٍ","en":"Ṭā, Seen. These are the verses of the Qur’ān [i.e., recitation] and a clear Book","ur":"ٰطٰسٓ۔ یہ قرآن اور روشن کتاب کی آیتیں ہیں","hi":"ता, सीन। ये क़ुरआन तथा स्पष्ट पुस्तक की आयतें हैं।"},{"a":2,"ar":"هُدًى وَبُشْرَىٰ لِلْمُؤْمِنِينَ","en":"As guidance and good tidings for the believers","ur":"مومنوں کے لئے ہدایت اور بشارت","hi":"ईमानवालों के लिए मार्गदर्शन तथा शुभ-सूचना हैं।"},{"a":3,"ar":"ٱلَّذِينَ يُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَهُم بِٱلْـَٔاخِرَةِ هُمْ يُوقِنُونَ","en":"Who establish prayer and give zakāh, and of the Hereafter they are certain [in faith].","ur":"وہ جو نماز پڑھتے اور زکوٰة دیتے اور آخرت کا یقین رکھتے ہیں","hi":"जो नमाज़ स्थापित करते तथा ज़कात देते हैं और वही हैं, जो आख़िरत (परलोक) पर विश्वास रखते हैं।"},{"a":4,"ar":"إِنَّ ٱلَّذِينَ لَا يُؤْمِنُونَ بِٱلْـَٔاخِرَةِ زَيَّنَّا لَهُمْ أَعْمَـٰلَهُمْ فَهُمْ يَعْمَهُونَ","en":"Indeed, for those who do not believe in the Hereafter, We have made pleasing to them their deeds, so they wander blindly.","ur":"جو لوگ آخرت پر ایمان نہیں رکھتے ہیں ہم نے ان کے اعمال ان کے لئے آرستہ کردیئے ہیں تو وہ سرگرداں ہو رہے ہیں","hi":"निःसंदेह जो लोग आख़िरत पर ईमान नहीं रखते, हमने उनके कर्मों को उनके लिए सुंदर बना दिया है। अतः वे भटकते फिरते है।"},{"a":5,"ar":"أُو۟لَـٰٓئِكَ ٱلَّذِينَ لَهُمْ سُوٓءُ ٱلْعَذَابِ وَهُمْ فِى ٱلْـَٔاخِرَةِ هُمُ ٱلْأَخْسَرُونَ","en":"Those are the ones for whom there will be the worst of punishment, and in the Hereafter they are the greatest losers.","ur":"یہی لوگ ہیں جن کے لئے بڑا عذاب ہے اور وہ آخرت میں بھی وہ بہت نقصان اٹھانے والے ہیں","hi":"यही लोग हैं, जिनके लिए बुरी यातना है तथा आख़िरत में यही सबसे अधिक घाटा उठाने वाले हैं।"},{"a":6,"ar":"وَإِنَّكَ لَتُلَقَّى ٱلْقُرْءَانَ مِن لَّدُنْ حَكِيمٍ عَلِيمٍ","en":"And indeed, [O Muḥammad], you receive the Qur’ān from one Wise and Knowing.","ur":"اور تم کو قرآن (خدائے) حکیم وعلیم کی طرف سے عطا کیا جاتا ہے","hi":"और निःसंदेह आपको क़ुरर्आन एक पूर्ण हिकमत वाले, सब कुछ जानने वाले की ओर से दिया जाता है।"},{"a":7,"ar":"إِذْ قَالَ مُوسَىٰ لِأَهْلِهِۦٓ إِنِّىٓ ءَانَسْتُ نَارًا سَـَٔاتِيكُم مِّنْهَا بِخَبَرٍ أَوْ ءَاتِيكُم بِشِهَابٍ قَبَسٍ لَّعَلَّكُمْ تَصْطَلُونَ","en":"[Mention] when Moses said to his family, \"Indeed, I have perceived a fire. I will bring you from there information or will bring you a burning torch that you may warm yourselves.\"","ur":"جب موسیٰ نے اپنے گھر والوں سے کہا کہ میں نے آگ دیکھی ہے، میں وہاں سے (رستے) کا پتہ لاتا ہوں یا سلگتا ہوا انگارہ تمہارے پاس لاتا ہوں تاکہ تم تاپو","hi":"जब मूसा ने अपने घर वालों से कहा : निःसंदेह मैंने एक आग देखी है। मैं शीघ्र तुम्हारे पास उससे कोई समाचार लाऊँगा या तुम्हारे पास उससे सुलगाया हुआ अंगारा लेकर आऊँगा, ताकि तुम तापो।"},{"a":8,"ar":"فَلَمَّا جَآءَهَا نُودِىَ أَنۢ بُورِكَ مَن فِى ٱلنَّارِ وَمَنْ حَوْلَهَا وَسُبْحَـٰنَ ٱللَّهِ رَبِّ ٱلْعَـٰلَمِينَ","en":"But when he came to it, he was called, \"Blessed is whoever is at the fire and whoever is around it. And exalted is Allāh, Lord of the worlds.","ur":"جب موسیٰ اس کے پاس آئے تو ندا آئی کہ وہ جو آگ میں (تجلّی دکھاتا) ہے بابرکت ہے۔ اور جو آگ کے اردگرد ہیں اور خدا جو تمام عالم کا پروردگار ہے پاک ہے","hi":"फिर जब वह उसके पास आया, तो उसे आवाज़ दी गई : बरकत वाला है, वह जो इस आग में है तथा जो इसके आस-पास है। और अल्लाह पवित्र है, जाे सारे संसारों का पालनहार है।"},{"a":9,"ar":"يَـٰمُوسَىٰٓ إِنَّهُۥٓ أَنَا ٱللَّهُ ٱلْعَزِيزُ ٱلْحَكِيمُ","en":"O Moses, indeed it is I - Allāh, the Exalted in Might, the Wise.\"","ur":"اے موسیٰ میں ہی خدائے غالب ودانا ہوں","hi":"ऐ मूसा! निःसंदेह तथ्य यह है कि मैं ही अल्लाह हूँ। जो सबपर प्रभुत्वशाली, पूर्ण हिकमत वाला है।"},{"a":10,"ar":"وَأَلْقِ عَصَاكَ ۚ فَلَمَّا رَءَاهَا تَهْتَزُّ كَأَنَّهَا جَآنٌّ وَلَّىٰ مُدْبِرًا وَلَمْ يُعَقِّبْ ۚ يَـٰمُوسَىٰ لَا تَخَفْ إِنِّى لَا يَخَافُ لَدَىَّ ٱلْمُرْسَلُونَ","en":"And [he was told], \"Throw down your staff.\" But when he saw it writhing as if it were a snake, he turned in flight and did not return. [Allāh said], \"O Moses, fear not. Indeed, in My presence the messengers do not fear.","ur":"اور اپنی لاٹھی ڈال دو۔ جب اُسے دیکھا تو (اس طرح) ہل رہی تھی گویا سانپ ہے تو پیٹھ پھیر کر بھاگے اور پیچھے مڑ کر نہ دیکھا (حکم ہوا کہ) موسیٰ ڈرو مت۔ ہمارے پاس پیغمبر ڈرا نہیں کرتے","hi":"और अपनी लाठी फेंक दे । फिर जब उसने उसे देखा कि हिल रही है, जैसे वह कोई साँप हो, तो पीठ फेरकर भागा और पीछे न मुड़ा। ऐ मूसा! डरो मत, निःसंदेह मेरे पास रसूल नहीं डरते।"},{"a":11,"ar":"إِلَّا مَن ظَلَمَ ثُمَّ بَدَّلَ حُسْنًۢا بَعْدَ سُوٓءٍ فَإِنِّى غَفُورٌ رَّحِيمٌ","en":"Otherwise, he who wrongs, then substitutes good after evil - indeed, I am Forgiving and Merciful.","ur":"ہاں جس نے ظلم کیا پھر برائی کے بعد اسے نیکی سے بدل دیا تو میں بخشنے والا مہربان ہوں","hi":"परंतु जिसने अत्याचार किया, फिर बुराई के बाद उसे भलाई से बदल दिया, तो निःसंदेह मैं बहुत क्षमा करने वाला, अत्यंत दयावान् हूँ।"},{"a":12,"ar":"وَأَدْخِلْ يَدَكَ فِى جَيْبِكَ تَخْرُجْ بَيْضَآءَ مِنْ غَيْرِ سُوٓءٍ ۖ فِى تِسْعِ ءَايَـٰتٍ إِلَىٰ فِرْعَوْنَ وَقَوْمِهِۦٓ ۚ إِنَّهُمْ كَانُوا۟ قَوْمًا فَـٰسِقِينَ","en":"And put your hand into the opening of your garment [at the breast]; it will come out white without disease. [These are] among the nine signs [you will take] to Pharaoh and his people. Indeed, they have been a people defiantly disobedient.\"","ur":"اور اپنا ہاتھ اپنے گریبان میں ڈالو سفید نکلے گا۔ (ان دو معجزوں کے ساتھ جو) نو معجزوں میں (داخل ہیں) فرعون اور اس کی قوم کے پاس جاؤ کہ وہ بےحکم لوگ ہیں","hi":"और अपना हाथ अपने गरीबान में डाल। वह बिना किसी दोष के (चमकता हुआ) सफ़ेद निकलेगा; नौ निशानियों में से एक, फ़िरऔन तथा उसकी जाति की ओर। निःसंदेह वे अवज्ञाकारी लोग थे।"},{"a":13,"ar":"فَلَمَّا جَآءَتْهُمْ ءَايَـٰتُنَا مُبْصِرَةً قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ","en":"But when there came to them Our visible signs, they said, \"This is obvious magic.\"","ur":"جب ان کے پاس ہماری روشن نشانیاں پہنچیں، کہنے لگے یہ صریح جادو ہے","hi":"फिर जब हमारी निशानियाँ उनके पास आईं जो आँखें खोलने वाली थीं, तो उन्होंने कहा : यह खुला जादू है।"},{"a":14,"ar":"وَجَحَدُوا۟ بِهَا وَٱسْتَيْقَنَتْهَآ أَنفُسُهُمْ ظُلْمًا وَعُلُوًّا ۚ فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُفْسِدِينَ","en":"And they rejected them, while their [inner] selves were convinced thereof, out of injustice and haughtiness. So see how was the end of the corrupters.","ur":"اور بےانصافی اور غرور سے ان سے انکار کیا لیکن ان کے دل ان کو مان چکے تھے۔ سو دیکھ لو فساد کرنے والوں کا انجام کیسا ہوا","hi":"तथा उन्होंने अत्याचार एवं अभिमान के कारण उनका इनकार कर दिया। हालाँकि उनके दिलों को उनका विश्वास हो चुका था। तो देखो कि बिगाड़ पैदा करने वालों का परिणाम कैसा हुआ?"},{"a":15,"ar":"وَلَقَدْ ءَاتَيْنَا دَاوُۥدَ وَسُلَيْمَـٰنَ عِلْمًا ۖ وَقَالَا ٱلْحَمْدُ لِلَّهِ ٱلَّذِى فَضَّلَنَا عَلَىٰ كَثِيرٍ مِّنْ عِبَادِهِ ٱلْمُؤْمِنِينَ","en":"And We had certainly given to David and Solomon knowledge, and they said, \"Praise [is due] to Allāh, who has favored us over many of His believing servants.\"","ur":"اور ہم نے داؤد اور سلیمان کو علم بخشا اور انہوں نے کہا کہ خدا کا شکر ہے جس نے ہمیں بہت سے مومن بندوں پر فضلیت دی","hi":"और निःसंदेह हमने दाऊद तथा सुलैमान को ज्ञान प्रदान किया और उन दोनों ने कहा : सारी प्रशंसा अल्लाह के लिए है, जिसने हमें अपने बहुत-से ईमानवाले बंदों पर श्रेष्ठता प्रदान की।"},{"a":16,"ar":"وَوَرِثَ سُلَيْمَـٰنُ دَاوُۥدَ ۖ وَقَالَ يَـٰٓأَيُّهَا ٱلنَّاسُ عُلِّمْنَا مَنطِقَ ٱلطَّيْرِ وَأُوتِينَا مِن كُلِّ شَىْءٍ ۖ إِنَّ هَـٰذَا لَهُوَ ٱلْفَضْلُ ٱلْمُبِينُ","en":"And Solomon inherited David. He said, \"O people, we have been taught the language of birds, and we have been given from all things. Indeed, this is evident bounty.\"","ur":"اور سلیمان اور داؤد کے قائم مقام ہوئے۔ اور کہنے لگے کہ لوگو! ہمیں (خدا کی طرف سے) جانوروں کی بولی سکھائی گئی ہے اور ہر چیز عنایت فرمائی گئی ہے۔ بےشک یہ (اُس کا) صریح فضل ہے","hi":"और सुलैमान दाऊद का उत्तराधिकारी हुआ तथा उसने कहा : ऐ लोगो! हमें पक्षियों की बोली सिखाई गई तथा हमें हर चीज़ में से हिस्सा प्रदान किया गया है। निःसंदेह यह निश्चित रूप से स्पष्ट अनुग्रह है।"},{"a":17,"ar":"وَحُشِرَ لِسُلَيْمَـٰنَ جُنُودُهُۥ مِنَ ٱلْجِنِّ وَٱلْإِنسِ وَٱلطَّيْرِ فَهُمْ يُوزَعُونَ","en":"And gathered for Solomon were his soldiers of the jinn and men and birds, and they were [marching] in rows","ur":"اور سلیمان کے لئے جنوں اور انسانوں اور پرندوں کے لشکر جمع کئے گئے اور قسم وار کئے جاتے تھے","hi":"तथा सुलैमान के लिए जिन्नों तथा इनसानों और पक्षियों में से उसकी सेनाएँ इकट्ठी की गईं, फिर उन्हें अलग-अलग बांटा जाता था।"},{"a":18,"ar":"حَتَّىٰٓ إِذَآ أَتَوْا۟ عَلَىٰ وَادِ ٱلنَّمْلِ قَالَتْ نَمْلَةٌ يَـٰٓأَيُّهَا ٱلنَّمْلُ ٱدْخُلُوا۟ مَسَـٰكِنَكُمْ لَا يَحْطِمَنَّكُمْ سُلَيْمَـٰنُ وَجُنُودُهُۥ وَهُمْ لَا يَشْعُرُونَ","en":"Until, when they came upon the valley of the ants, an ant said, \"O ants, enter your dwellings that you not be crushed by Solomon and his soldiers while they perceive not.\"","ur":"یہاں تک کہ جب چیونٹیوں کے میدان میں پہنچے تو ایک چیونٹی نے کہا کہ چیونٹیوں اپنے اپنے بلوں میں داخل ہو جاؤ ایسا نہ ہو کہ سلیمان اور اس کے لشکر تم کو کچل ڈالیں اور ان کو خبر بھی نہ ہو","hi":"यहाँ तक कि जब वे चींटियों की घाटी में पहुँचे, तो एक चींटी ने कहा : ऐ चींटियो! अपने घरों में प्रवेश कर जाओ। कहीं सुलैमान और उसकी सेनाएँ तुम्हें कुचल न डालें और वे अनजान हों।"},{"a":19,"ar":"فَتَبَسَّمَ ضَاحِكًا مِّن قَوْلِهَا وَقَالَ رَبِّ أَوْزِعْنِىٓ أَنْ أَشْكُرَ نِعْمَتَكَ ٱلَّتِىٓ أَنْعَمْتَ عَلَىَّ وَعَلَىٰ وَٰلِدَىَّ وَأَنْ أَعْمَلَ صَـٰلِحًا تَرْضَىٰهُ وَأَدْخِلْنِى بِرَحْمَتِكَ فِى عِبَادِكَ ٱلصَّـٰلِحِينَ","en":"So [Solomon] smiled, amused at her speech, and said, \"My Lord, enable me to be grateful for Your favor which You have bestowed upon me and upon my parents and to do righteousness of which You approve. And admit me by Your mercy into [the ranks of] Your righteous servants.\"","ur":"تو وہ اس کی بات سن کر ہنس پڑے اور کہنے لگے کہ اے پروردگار! مجھے توفیق عطا فرما کہ جو احسان تونے مجھ پر اور میرے ماں باپ پر کئے ہیں ان کا شکر کروں اور ایسے نیک کام کروں کہ تو ان سے خوش ہوجائے اور مجھے اپنی رحمت سے اپنے نیک بندوں میں داخل فرما","hi":"तो वह (सुलैमान) उसकी बात से हँसता हुआ मुसकुराया और उसने कहा : ऐ मेरे पालनहार! मुझे सामर्थ्य प्रदान कर कि मैं तेरी उस ने'मत का शुक्र अदा करूँ, जो तूने मुझे तथा मेरे माता-पिता को प्रदान की है, और यह कि मैं अच्छा कार्य करूँ, जिसे तू पसंद करे और मुझे अपनी दया से अपने सदाचारी बंदों में शामिल कर ले।"},{"a":20,"ar":"وَتَفَقَّدَ ٱلطَّيْرَ فَقَالَ مَا لِىَ لَآ أَرَى ٱلْهُدْهُدَ أَمْ كَانَ مِنَ ٱلْغَآئِبِينَ","en":"And he took attendance of the birds and said, \"Why do I not see the hoopoe - or is he among the absent?","ur":"انہوں نے جانوروں کا جائزہ لیا تو کہنے لگے کیا سبب ہے کہ ہُدہُد نظر نہیں آتا۔ کیا کہیں غائب ہوگیا ہے؟","hi":"और उसने पक्षियों का निरीक्षण किया, तो कहा : मुझे क्या है कि मैं हुदहुद को नहीं देख रहा, या वह अनुपस्थि रहने वालों में से है?"},{"a":21,"ar":"لَأُعَذِّبَنَّهُۥ عَذَابًا شَدِيدًا أَوْ لَأَا۟ذْبَحَنَّهُۥٓ أَوْ لَيَأْتِيَنِّى بِسُلْطَـٰنٍ مُّبِينٍ","en":"I will surely punish him with a severe punishment or slaughter him unless he brings me clear authorization.\"","ur":"میں اسے سخت سزا دوں گا یا ذبح کر ڈالوں گا یا میرے سامنے (اپنی بےقصوری کی) دلیل صریح پیش کرے","hi":"निश्चय ही मैं उसे बहुत कठोर दंड दूँगा, या मैं अवश्य ही उसे ज़बह कर डालूँगा, या वह अवश्य ही मेरे पास कोई स्पष्ट तर्क लेकर आएगा।"},{"a":22,"ar":"فَمَكَثَ غَيْرَ بَعِيدٍ فَقَالَ أَحَطتُ بِمَا لَمْ تُحِطْ بِهِۦ وَجِئْتُكَ مِن سَبَإٍۭ بِنَبَإٍ يَقِينٍ","en":"But he [i.e., the hoopoe] stayed not long and said, \"I have encompassed [in knowledge] that which you have not encompassed, and I have come to you from Sheba with certain news.","ur":"ابھی تھوڑی ہی دیر ہوئی تھی کہ ہُدہُد آ موجود ہوا اور کہنے لگا کہ مجھے ایک ایسی چیز معلوم ہوئی ہے جس کی آپ کو خبر نہیں اور میں آپ کے پاس (شہر) سبا سے ایک سچی خبر لے کر آیا ہوں","hi":"फिर कुछ अधिक देर नहीं ठहरा कि उसने (आकर) कहा : मैं ऐसी बात से अवगत हुआ हूँ, जिससे आप अवगत नहीं हुए और मैं आपके पास 'सबा' से एक पक्की ख़बर लाया हूँ।"},{"a":23,"ar":"إِنِّى وَجَدتُّ ٱمْرَأَةً تَمْلِكُهُمْ وَأُوتِيَتْ مِن كُلِّ شَىْءٍ وَلَهَا عَرْشٌ عَظِيمٌ","en":"Indeed, I found [there] a woman ruling them, and she has been given of all things, and she has a great throne.","ur":"میں نے ایک عورت دیکھی کہ ان لوگوں پر بادشاہت کرتی ہے اور ہر چیز اسے میسر ہے اور اس کا ایک بڑا تخت ہے","hi":"निःसंदेह मैंने एक महिला को पाया, जो उनपर शासन कर रही है तथा उसे हर चीज़ का हिस्सा दिया गया है और उसके पास एक बड़ा सिंहासन है।"},{"a":24,"ar":"وَجَدتُّهَا وَقَوْمَهَا يَسْجُدُونَ لِلشَّمْسِ مِن دُونِ ٱللَّهِ وَزَيَّنَ لَهُمُ ٱلشَّيْطَـٰنُ أَعْمَـٰلَهُمْ فَصَدَّهُمْ عَنِ ٱلسَّبِيلِ فَهُمْ لَا يَهْتَدُونَ","en":"I found her and her people prostrating to the sun instead of Allāh, and Satan has made their deeds pleasing to them and averted them from [His] way, so they are not guided,","ur":"میں نے دیکھا کہ وہ اور اس کی قوم خدا کو چھوڑ کر آفتاب کو سجدہ کرتے ہیں اور شیطان نے ان کے اعمال انہیں آراستہ کر دکھائے ہیں اور ان کو رستے سے روک رکھا ہے پس وہ رستے پر نہیں آئے","hi":"मैंने उसे तथा उसकी जाति को अल्लाह के सिवा सूर्य को सजदा करते हुए पाया और शैतान ने उनके कामों को उनके लिए शोभित कर दिया है। चुनाँचे उन्हें सुपथ से रोक दिया है। अतः वे मार्गदर्शन नहीं पाते।"},{"a":25,"ar":"أَلَّا يَسْجُدُوا۟ لِلَّهِ ٱلَّذِى يُخْرِجُ ٱلْخَبْءَ فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَيَعْلَمُ مَا تُخْفُونَ وَمَا تُعْلِنُونَ","en":"[And] so they do not prostrate to Allāh, who brings forth what is hidden within the heavens and the earth and knows what you conceal and what you declare -","ur":"(اور نہیں سمجھتے) کہ خدا کو آسمانوں اور زمین میں چھپی چیزوں کو ظاہر کردیتا اور تمہارے پوشیدہ اور ظاہر اعمال کو جانتا ہے کیوں سجدہ نہ کریں","hi":"(शैतान ने उनके कामों को उनके लिए शोभित कर दिया है) ताकि वे उस अल्लाह को सजदा न करें, जो आकाशों तथा धरती में छिपी चीज़ों को निकालता है तथा वह जानता है जो तुम छिपाते हो और जो प्रकट करते हो।"},{"a":26,"ar":"ٱللَّهُ لَآ إِلَـٰهَ إِلَّا هُوَ رَبُّ ٱلْعَرْشِ ٱلْعَظِيمِ ۩","en":"Allāh - there is no deity except Him, Lord of the Great Throne.\"","ur":"خدا کے سوا کوئی عبادت کے لائق نہیں وہی عرش عظیم کا مالک ہے","hi":"अल्लाह वह है जिसके सिवा कोई पूज्य नहीं, जो महान सिंहासन का रब है।"},{"a":27,"ar":"۞ قَالَ سَنَنظُرُ أَصَدَقْتَ أَمْ كُنتَ مِنَ ٱلْكَـٰذِبِينَ","en":"[Solomon] said, \"We will see whether you were truthful or were of the liars.","ur":"سلیمان نے کہا (اچھا) ہم دیکھیں گے، تونے سچ کہا ہے یا تو جھوٹا ہے","hi":"(सुलैमान ने) कहा : हम देखेंगे कि तूने सच कहा, या तू झूठों में से था।"},{"a":28,"ar":"ٱذْهَب بِّكِتَـٰبِى هَـٰذَا فَأَلْقِهْ إِلَيْهِمْ ثُمَّ تَوَلَّ عَنْهُمْ فَٱنظُرْ مَاذَا يَرْجِعُونَ","en":"Take this letter of mine and deliver it to them. Then leave them and see what [answer] they will return.\"","ur":"یہ میرا خط لے جا اور اسے ان کی طرف ڈال دے پھر ان کے پاس سے پھر آ اور دیکھ کہ وہ کیا جواب دیتے ہیں","hi":"मेरा यह पत्र लेकर जा और इसे उनकी ओर डाल दे। फिर उनसे अलग हटकर देख कि वे क्या जवाब देते हैं।"},{"a":29,"ar":"قَالَتْ يَـٰٓأَيُّهَا ٱلْمَلَؤُا۟ إِنِّىٓ أُلْقِىَ إِلَىَّ كِتَـٰبٌ كَرِيمٌ","en":"She said, \"O eminent ones, indeed, to me has been delivered a noble letter.","ur":"ملکہ نے کہا کہ دربار والو! میری طرف ایک نامہ گرامی ڈالا گیا ہے","hi":"उस (रानी) ने कहा : ऐ सरदारो! निःसंदेह मेरी ओर एक प्रतिष्ठित पत्र फेंका गया है।"},{"a":30,"ar":"إِنَّهُۥ مِن سُلَيْمَـٰنَ وَإِنَّهُۥ بِسْمِ ٱللَّهِ ٱلرَّحْمَـٰنِ ٱلرَّحِيمِ","en":"Indeed, it is from Solomon, and indeed, it is [i.e., reads]: 'In the name of Allāh, the Entirely Merciful, the Especially Merciful,","ur":"وہ سلیمان کی طرف سے ہے اور مضمون یہ ہے کہ شروع خدا کا نام لے کر جو بڑا مہربان نہایت رحم والا ہے","hi":"निःसंदेह वह सुलैमान की ओर से है और निःसंदेह वह अल्लाह के नाम से है, जो अत्यंत कृपाशील, असीम दयावान् है।"},{"a":31,"ar":"أَلَّا تَعْلُوا۟ عَلَىَّ وَأْتُونِى مُسْلِمِينَ","en":"Be not haughty with me but come to me in submission [as Muslims].'\"","ur":"(بعد اس کے یہ) کہ مجھے سرکشی نہ کرو اور مطیع ومنقاد ہو کر میرے پاس چلے آؤ","hi":"यह कि मेरे मुक़ाबले में सरकशी न करो तथा आज्ञाकारी होकर मेरे पास आ जाओ।"},{"a":32,"ar":"قَالَتْ يَـٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَفْتُونِى فِىٓ أَمْرِى مَا كُنتُ قَاطِعَةً أَمْرًا حَتَّىٰ تَشْهَدُونِ","en":"She said, \"O eminent ones, advise me in my affair. I would not decide a matter until you witness [for] me.\"","ur":"(خط سنا کر) وہ کہنے لگی کہ اے اہل دربار میرے اس معاملے میں مجھے مشورہ دو، جب تک تم حاضر نہ ہو (اور صلاح نہ دو) میں کسی کام کو فیصل کرنے والی نہیں","hi":"उसने कहा : ऐ प्रमुखो! मुझे मेरे मामले में सही हल बताओ। मैं किसी मामले का फ़ैसला करने वाली नहीं, यहाँ तक तुम मेरे पास उपस्थित हो।"},{"a":33,"ar":"قَالُوا۟ نَحْنُ أُو۟لُوا۟ قُوَّةٍ وَأُو۟لُوا۟ بَأْسٍ شَدِيدٍ وَٱلْأَمْرُ إِلَيْكِ فَٱنظُرِى مَاذَا تَأْمُرِينَ","en":"They said, \"We are men of strength and of great military might, but the command is yours, so see what you will command.\"","ur":"وہ بولے کہ ہم بڑے زورآور اور سخت جنگجو ہیں اور حکم آپ کے اختیار ہے تو جو حکم دیجیئے گا (اس کے مآل پر) نظر کرلیجیئے گا","hi":"उन्होंने कहा : हम बड़े पराक्रमी और प्रखर योद्धा हैं और मामला आपके हवाले है, सो देखे लें आप क्या आदेश देती हैं।"},{"a":34,"ar":"قَالَتْ إِنَّ ٱلْمُلُوكَ إِذَا دَخَلُوا۟ قَرْيَةً أَفْسَدُوهَا وَجَعَلُوٓا۟ أَعِزَّةَ أَهْلِهَآ أَذِلَّةً ۖ وَكَذَٰلِكَ يَفْعَلُونَ","en":"She said, \"Indeed kings - when they enter a city, they ruin it and render the honored of its people humbled. And thus do they do.","ur":"اس نے کہا کہ بادشاہ جب کسی شہر میں داخل ہوتے ہیں تو اس کو تباہ کر دیتے ہیں اور وہاں کے عزت والوں کو ذلیل کر دیا کرتے ہیں اور اسی طرح یہ بھی کریں گے","hi":"उसने कहा : निःसंदेह राजा जब किसी बस्ती में प्रवेश करते हैं, तो उसे ख़राब कर देते हैं और उसके वासियों में से प्रतिष्ठित लोगों को अपमानित कर देते हैं। और इसी तरह ये करेंगे।"},{"a":35,"ar":"وَإِنِّى مُرْسِلَةٌ إِلَيْهِم بِهَدِيَّةٍ فَنَاظِرَةٌۢ بِمَ يَرْجِعُ ٱلْمُرْسَلُونَ","en":"But indeed, I will send to them a gift and see with what [reply] the messengers will return.\"","ur":"اور میں ان کی طرف کچھ تحفہ بھیجتی ہوں اور دیکھتی ہوں کہ قاصد کیا جواب لاتے ہیں","hi":"और निःसंदेह मैं उनकी ओर एक उपहार भेजने वाली हूँ। फिर देखती हूँ कि दूत क्या उत्तर लेकर आते हैं?"},{"a":36,"ar":"فَلَمَّا جَآءَ سُلَيْمَـٰنَ قَالَ أَتُمِدُّونَنِ بِمَالٍ فَمَآ ءَاتَىٰنِۦَ ٱللَّهُ خَيْرٌ مِّمَّآ ءَاتَىٰكُم بَلْ أَنتُم بِهَدِيَّتِكُمْ تَفْرَحُونَ","en":"So when they came to Solomon, he said, \"Do you provide me with wealth? But what Allāh has given me is better than what He has given you. Rather, it is you who rejoice in your gift.","ur":"جب (قاصد) سلیمان کے پاس پہنچا تو سلیمان نے کہا کیا تم مجھے مال سے مدد دینا چاہتے ہو، جو کچھ خدا نے مجھے عطا فرمایا ہے وہ اس سے بہتر ہے جو تمہیں دیا ہے حقیقت یہ ہے کہ تم ہی اپنے تحفے سے خوش ہوتے ہوگے","hi":"तो जब वह (दूत) सुलैमान के पास आया, तो उसने कहा : क्या तुम धन से मेरी सहायता करते हो? तो जो कुछ अल्लाह ने मुझे दिया है, वह उससे बेहतर है जो उसने तुम्हें दिया है, बल्कि तुम ही लोग अपने उपहारों पर खुश होते हो।"},{"a":37,"ar":"ٱرْجِعْ إِلَيْهِمْ فَلَنَأْتِيَنَّهُم بِجُنُودٍ لَّا قِبَلَ لَهُم بِهَا وَلَنُخْرِجَنَّهُم مِّنْهَآ أَذِلَّةً وَهُمْ صَـٰغِرُونَ","en":"Return to them, for we will surely come to them with soldiers that they will be powerless to encounter, and we will surely expel them therefrom in humiliation, and they will be debased.\"","ur":"ان کے پاس واپس جاؤ ہم ان پر ایسے لشکر سے حملہ کریں گے جس کے مقابلے کی ان میں طاقت نہ ہوگی اور ان کو وہاں سے بےعزت کرکے نکال دیں گے اور وہ ذلیل ہوں گے","hi":"उनके पास वापस जाओ, अब हम अवश्य उनके पास ऐसी सेनाएँ लेकर आएँगे, जिनका वे सामना नहीं कर सकेंगे और हम अवश्य उन्हें उस (बस्ती) से इस तरह अपमानित करके निकाल देंगे कि वे तुच्छ होंगे।"},{"a":38,"ar":"قَالَ يَـٰٓأَيُّهَا ٱلْمَلَؤُا۟ أَيُّكُمْ يَأْتِينِى بِعَرْشِهَا قَبْلَ أَن يَأْتُونِى مُسْلِمِينَ","en":"[Solomon] said, \"O assembly [of jinn], which of you will bring me her throne before they come to me in submission?\"","ur":"سلیمان نے کہا کہ اے دربار والو! کوئی تم میں ایسا ہے کہ قبل اس کے کہ وہ لوگ فرمانبردار ہو کر ہمارے پاس آئیں ملکہ کا تخت میرے پاس لے آئے","hi":"(सुलैमान ने) कहा : ऐ प्रमुखो! तुममें से कौन उसका सिंहासन मेरे पास लेकर आएगा, इससे पहले कि वे आज्ञाकारी होकर मेरे पास आएँ।"},{"a":39,"ar":"قَالَ عِفْرِيتٌ مِّنَ ٱلْجِنِّ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن تَقُومَ مِن مَّقَامِكَ ۖ وَإِنِّى عَلَيْهِ لَقَوِىٌّ أَمِينٌ","en":"A powerful one from among the jinn said, \"I will bring it to you before you rise from your place, and indeed, I am for this [task] strong and trustworthy.\"","ur":"جنات میں سے ایک قوی ہیکل جن نے کہا کہ قبل اس کے کہ آپ اپنی جگہ سے اٹھیں میں اس کو آپ کے پاس لاحاضر کرتا ہوں اور میں اس (کے اٹھانے کی) طاقت رکھتا ہوں (اور) امانت دار ہوں","hi":"जिन्नों में से एक शक्तिशाली शरारती कहने लगा : मैं उसे आपके पास ले आऊँगा, इससे पूर्व कि आप अपने स्थान से उठें और निःसंदेह मैं इसकी निश्चय पूरी शक्ति रखने वाला, अमानतदार हूँ।"},{"a":40,"ar":"قَالَ ٱلَّذِى عِندَهُۥ عِلْمٌ مِّنَ ٱلْكِتَـٰبِ أَنَا۠ ءَاتِيكَ بِهِۦ قَبْلَ أَن يَرْتَدَّ إِلَيْكَ طَرْفُكَ ۚ فَلَمَّا رَءَاهُ مُسْتَقِرًّا عِندَهُۥ قَالَ هَـٰذَا مِن فَضْلِ رَبِّى لِيَبْلُوَنِىٓ ءَأَشْكُرُ أَمْ أَكْفُرُ ۖ وَمَن شَكَرَ فَإِنَّمَا يَشْكُرُ لِنَفْسِهِۦ ۖ وَمَن كَفَرَ فَإِنَّ رَبِّى غَنِىٌّ كَرِيمٌ","en":"Said one who had knowledge from the Scripture, \"I will bring it to you before your glance returns to you.\" And when [Solomon] saw it placed before him, he said, \"This is from the favor of my Lord to test me whether I will be grateful or ungrateful. And whoever is grateful - his gratitude is only for [the benefit of] himself. And whoever is ungrateful - then indeed, my Lord is Free of need and Generous.\"","ur":"ایک شخص جس کو کتاب الہیٰ کا علم تھا کہنے لگا کہ میں آپ کی آنکھ کے جھپکنے سے پہلے پہلے اسے آپ کے پاس حاضر کئے دیتا ہوں۔ جب سلیمان نے تخت کو اپنے پاس رکھا ہوا دیکھا تو کہا کہ یہ میرے پروردگار کا فضل ہے تاکہ مجھے آزمائے کہ میں شکر کرتا ہوں یا کفران نعمت کرتا ہوں اور جو شکر کرتا ہے تو اپنے ہی فائدے کے لئے شکر کرتا ہے اور جو ناشکری کرتا ہے تو میرا پروردگار بےپروا (اور) کرم کرنے والا ہے","hi":"जिसके पास पुस्तक का ज्ञान था, उसने कहा : मैं उसे आपके पास इससे पहले ले आता हूँ कि आपकी पलक झपके। और जब उसने उसे अपने पास रखा हुआ देखा, तो कहा : यह मेरे पालनहार का अनुग्रह है, ताकि मेरी परीक्षा ले कि मैं शुक्र अदा करता हूँ या नाशुक्री करता हूँ। और जिसने शुक्र किया, तो वह अपने ही लिए शुक्र करता है तथा जिसने नाशुक्री की, तो निश्चय मेरा पालनहार बहुत बेनियाज़, अत्यंत उदार है।"},{"a":41,"ar":"قَالَ نَكِّرُوا۟ لَهَا عَرْشَهَا نَنظُرْ أَتَهْتَدِىٓ أَمْ تَكُونُ مِنَ ٱلَّذِينَ لَا يَهْتَدُونَ","en":"He said, \"Disguise for her her throne; we will see whether she will be guided [to truth] or will be of those who is not guided.\"","ur":"سلیمان نے کہا کہ ملکہ کے (امتحان عقل کے) لئے اس کے تخت کی صورت بدل دو۔ دیکھیں کہ وہ سوجھ رکھتی ہے یا ان لوگوں میں ہے جو سوجھ نہیں رکھتے","hi":"(सुलैमान ने) कहा : उसके लिए उसके सिंहासन का रंग-रूप बदल दो। ताकि हम देखें क्या वह राह पा लेती है या उनमें से होती है, जो राह नहीं पाते।"},{"a":42,"ar":"فَلَمَّا جَآءَتْ قِيلَ أَهَـٰكَذَا عَرْشُكِ ۖ قَالَتْ كَأَنَّهُۥ هُوَ ۚ وَأُوتِينَا ٱلْعِلْمَ مِن قَبْلِهَا وَكُنَّا مُسْلِمِينَ","en":"So when she arrived, it was said [to her], \"Is your throne like this?\" She said, \"[It is] as though it was it.\" [Solomon said], \"And we were given knowledge before her, and we have been Muslims [in submission to Allāh].","ur":"جب وہ آ پہنچی تو پوچھا گیا کہ کیا آپ کا تخت بھی اسی طرح کا ہے؟ اس نے کہا کہ یہ تو گویا ہو بہو وہی ہے اور ہم کو اس سے پہلے ہی (سلیمان کی عظمت شان) کا علم ہوگیا تھا اور ہم فرمانبردار ہیں","hi":"फिर जब वह आई, तो उससे कहा गया : क्या तेरा सिंहासन ऐसा ही है? उसने कहा : यह तो मानो वही है, और हमें इससे पहले ज्ञान दिया गया था, और हम आज्ञाकारी थे।"},{"a":43,"ar":"وَصَدَّهَا مَا كَانَت تَّعْبُدُ مِن دُونِ ٱللَّهِ ۖ إِنَّهَا كَانَتْ مِن قَوْمٍ كَـٰفِرِينَ","en":"And that which she was worshipping other than Allāh had averted her [from submission to Him]. Indeed, she was from a disbelieving people.\"","ur":"اور وہ جو خدا کے سوا (اور کی) پرستش کرتی تھی، سلیمان نے اس کو اس سے منع کیا (اس سے پہلے تو) وہ کافروں میں سے تھی","hi":"और उसे (ईमान से) उस चीज़ ने रोक रखा था, जिसकी वह अल्लाह के सिवा इबादत कर रही थी। निःसंदेह वह काफ़िर लोगों में से थी।"},{"a":44,"ar":"قِيلَ لَهَا ٱدْخُلِى ٱلصَّرْحَ ۖ فَلَمَّا رَأَتْهُ حَسِبَتْهُ لُجَّةً وَكَشَفَتْ عَن سَاقَيْهَا ۚ قَالَ إِنَّهُۥ صَرْحٌ مُّمَرَّدٌ مِّن قَوَارِيرَ ۗ قَالَتْ رَبِّ إِنِّى ظَلَمْتُ نَفْسِى وَأَسْلَمْتُ مَعَ سُلَيْمَـٰنَ لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ","en":"She was told, \"Enter the palace.\" But when she saw it, she thought it was a body of water and uncovered her shins [to wade through]. He said, \"Indeed, it is a palace [whose floor is] made smooth with glass.\" She said, \"My Lord, indeed I have wronged myself, and I submit with Solomon to Allāh, Lord of the worlds.\"","ur":"(پھر) اس سے کہا گیا کہ محل میں چلیے، جب اس نے اس (کے فرش) کو دیکھا تو اسے پانی کا حوض سمجھا اور (کپڑا اٹھا کر) اپنی پنڈلیاں کھول دیں۔ سلیمان نے کہا یہ ایسا محل ہے جس میں (نیچے بھی) شیشے جڑے ہوئے ہیں۔ وہ بول اٹھی کہ پروردگار میں اپنے آپ پر ظلم کرتی رہی تھی اور (اب) میں سلیمان کے ہاتھ پر خدائے رب العالمین پر ایمان لاتی ہوں","hi":"उससे कहा गया : इस महल में प्रवेश कर जाओ। तो जब उसने उसे देखा, तो उसे गहरा पानी समझा और अपनी दोनों पिंडलियाँ से कपड़ा उठा लिया। (सुलैमान ने) कहा : यह तो शीशे से मढ़ा हुआ चिकना महल है। उसने कहा : ऐ मेरे पालनहार! निःसंदेह मैंने अपने प्राण पर अत्याचार किया है और (अब) मैं सुलैमान के साथ सारे संसारों के पालनहार अल्लाह के लिए आज्ञाकारिणी हो गई।"},{"a":45,"ar":"وَلَقَدْ أَرْسَلْنَآ إِلَىٰ ثَمُودَ أَخَاهُمْ صَـٰلِحًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ فَإِذَا هُمْ فَرِيقَانِ يَخْتَصِمُونَ","en":"And We had certainly sent to Thamūd their brother Ṣāliḥ, [saying], \"Worship Allāh,\" and at once they were two parties conflicting.","ur":"اور ہم نے ثمود کی طرف اس کے بھائی صالح کو بھیجا کہ خدا کی عبادت کرو تو وہ دو فریق ہو کر آپس میں جھگڑنے لگے","hi":"और निःसंदेह हमने समूद की ओर उनके भाई सालेह़ को भेजा कि तुम सब अल्लाह की इबादत करो, तो अचानक वे दो समूहों में बंटकर झगड़ने लगे।"},{"a":46,"ar":"قَالَ يَـٰقَوْمِ لِمَ تَسْتَعْجِلُونَ بِٱلسَّيِّئَةِ قَبْلَ ٱلْحَسَنَةِ ۖ لَوْلَا تَسْتَغْفِرُونَ ٱللَّهَ لَعَلَّكُمْ تُرْحَمُونَ","en":"He said, \"O my people, why are you impatient for evil before [i.e., instead of] good? Why do you not seek forgiveness of Allāh that you may receive mercy?\"","ur":"صالح نے کہا کہ بھائیو تم بھلائی سے پہلے برائی کے لئے کیوں جلدی کرتے ہو (اور) خدا سے بخشش کیوں نہیں مانگتے تاکہ تم پر رحم کیا جائے","hi":"(सालेह ने) कहा : ऐ मेरी जाति के लोगो! तुम भलाई से पहले बुराई क्यों जल्दी माँगते हो? तुम अल्लाह से क्षमा क्यों नहीं माँगते, ताकि तुम पर दया की जाए?"},{"a":47,"ar":"قَالُوا۟ ٱطَّيَّرْنَا بِكَ وَبِمَن مَّعَكَ ۚ قَالَ طَـٰٓئِرُكُمْ عِندَ ٱللَّهِ ۖ بَلْ أَنتُمْ قَوْمٌ تُفْتَنُونَ","en":"They said, \"We consider you a bad omen, you and those with you.\" He said, \"Your omen [i.e., fate] is with Allāh. Rather, you are a people being tested.\"","ur":"وہ کہنے لگے کہ تم اور تمہارے ساتھی ہمارے لئے شگون بد ہے۔ صالح نے کہا کہ تمہاری بدشگونی خدا کی طرف سے ہے بلکہ تم ایسے لوگ ہو جن کی آزمائش کی جاتی ہے","hi":"उन्होंने कहा : हमने तुमपर तथा तुम्हारे साथियों पर अपशकुन पाया है। (सालेह़ ने) कहा : तुम्हारा अपशकुन अल्लाह के पास है, बल्कि तुम ऐसे लोग हो जिनकी परीक्षा ली जा रही है।"},{"a":48,"ar":"وَكَانَ فِى ٱلْمَدِينَةِ تِسْعَةُ رَهْطٍ يُفْسِدُونَ فِى ٱلْأَرْضِ وَلَا يُصْلِحُونَ","en":"And there were in the city nine family heads causing corruption in the land and not amending [its affairs].","ur":"اور شہر میں نو شخص تھے جو ملک میں فساد کیا کرتے تھے اور اصلاح سے کام نہیں لیتے تھے","hi":"और उस नगर में नौ (9) लोग थे, जो धरती में उत्पात मचाते थे और सुधार नहीं करते थे।"},{"a":49,"ar":"قَالُوا۟ تَقَاسَمُوا۟ بِٱللَّهِ لَنُبَيِّتَنَّهُۥ وَأَهْلَهُۥ ثُمَّ لَنَقُولَنَّ لِوَلِيِّهِۦ مَا شَهِدْنَا مَهْلِكَ أَهْلِهِۦ وَإِنَّا لَصَـٰدِقُونَ","en":"They said, \"Take a mutual oath by Allāh that we will kill him by night, he and his family. Then we will say to his executor, 'We did not witness the destruction of his family, and indeed, we are truthful.'\"","ur":"کہنے لگے کہ خدا کی قسم کھاؤ کہ ہم رات کو اس پر اور اس کے گھر والوں پر شب خون ماریں گے پھر اس کے وارث سے کہہ دیں گے کہ ہم تو صالح کے گھر والوں کے موقع ہلاکت پر گئے ہی نہیں اور ہم سچ کہتے ہیں","hi":"उन्होंने कहा : आपस में अल्लाह की क़सम खाओ कि हम अवश्य ही उसपर और उसके परिवार पर रात में हमला करेंगे, फिर हम अवश्य ही उसके वारिस (उत्तराधिकारी) से कह देंगे : हम उसके परिवार की मृत्यु के समय मौजूद नहीं थे। और निःसंदेह हम अवश्य सच्चे हैं।"},{"a":50,"ar":"وَمَكَرُوا۟ مَكْرًا وَمَكَرْنَا مَكْرًا وَهُمْ لَا يَشْعُرُونَ","en":"And they planned a plan, and We planned a plan, while they perceived not.","ur":"اور وہ ایک چال چلے اور ان کو کچھ خبر نہ ہوئی","hi":"और उन्होंने एक चाल चली और हमने भी एक चाल चली और वे सोचते तक न थे।"},{"a":51,"ar":"فَٱنظُرْ كَيْفَ كَانَ عَـٰقِبَةُ مَكْرِهِمْ أَنَّا دَمَّرْنَـٰهُمْ وَقَوْمَهُمْ أَجْمَعِينَ","en":"Then look how was the outcome of their plan - that We destroyed them and their people, all.","ur":"تو دیکھ لو ان کی چال کا کیسا انجام ہوا۔ ہم نے ان کو اور ان کی قوم سب کو ہلاک کر ڈالا","hi":"तो देखो उनकी चाल का परिणाम कैसा हुआ कि निःसंदेह हमने उन्हें और उनकी क़ौम, सबको विनष्ट कर दिया।"},{"a":52,"ar":"فَتِلْكَ بُيُوتُهُمْ خَاوِيَةًۢ بِمَا ظَلَمُوٓا۟ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَعْلَمُونَ","en":"So those are their houses, desolate because of the wrong they had done. Indeed in that is a sign for people who know.","ur":"اب یہ ان کے گھر ان کے ظلم کے سبب خالی پڑے ہیں۔ جو لوگ دانش رکھتے ہیں، ان کے لئے اس میں نشانی ہے","hi":"तो ये हैं उनके घर, उनके ज़ुल्म के कारण गिर हुए। निःसंदेह इसमें उन लोगों के लिए निश्चय एक निशानी है, जो ज्ञान रखते हैं।"},{"a":53,"ar":"وَأَنجَيْنَا ٱلَّذِينَ ءَامَنُوا۟ وَكَانُوا۟ يَتَّقُونَ","en":"And We saved those who believed and used to fear Allāh.","ur":"اور جو لوگ ایمان لائے اور ڈرتے تھے ان کو ہم نے نجات دی","hi":"तथा हमने उन लोगों को बचा लिया, जो ईमान लाए और डरते रहे थे।"},{"a":54,"ar":"وَلُوطًا إِذْ قَالَ لِقَوْمِهِۦٓ أَتَأْتُونَ ٱلْفَـٰحِشَةَ وَأَنتُمْ تُبْصِرُونَ","en":"And [mention] Lot, when he said to his people, \"Do you commit immorality while you are seeing?","ur":"اور لوط کو (یاد کرو) جب انہوں نے اپنی قوم سے کہا کہ تم بےحیائی (کے کام) کیوں کرتے ہو اور تم دیکھتے ہو","hi":"तथा (हमने) लूत को (भेजा), जब उसने अपनी जाति के लोगों से कहा : क्या तुम अश्लील काम करते हो, जबकि तुम देखते हो?"},{"a":55,"ar":"أَئِنَّكُمْ لَتَأْتُونَ ٱلرِّجَالَ شَهْوَةً مِّن دُونِ ٱلنِّسَآءِ ۚ بَلْ أَنتُمْ قَوْمٌ تَجْهَلُونَ","en":"Do you indeed approach men with desire instead of women? Rather, you are a people behaving ignorantly.\"","ur":"کیا تم عورتوں کو چھوڑ کر (لذت حاصل کرنے) کے لئے مردوں کی طرف مائل ہوتے ہو۔ حقیقت یہ ہے کہ تم احمق لوگ ہو","hi":"क्या तुम सचमुच स्त्रियों को छोड़कर वासनावश पुरुषों के पास आते हो? बल्कि तुम बड़े ही नासमझ लोग हो।"},{"a":56,"ar":"۞ فَمَا كَانَ جَوَابَ قَوْمِهِۦٓ إِلَّآ أَن قَالُوٓا۟ أَخْرِجُوٓا۟ ءَالَ لُوطٍ مِّن قَرْيَتِكُمْ ۖ إِنَّهُمْ أُنَاسٌ يَتَطَهَّرُونَ","en":"But the answer of his people was not except that they said, \"Expel the family of Lot from your city. Indeed, they are people who keep themselves pure.\"","ur":"تو ان کی قوم کے لوگ (بولے تو) یہ بولے اور اس کے سوا ان کا کچھ جواب نہ تھا کہ لوط کے گھر والوں کو اپنے شہر سے نکال دو۔ یہ لوگ پاک رہنا چاہتے ہیں","hi":"तो उसकी जाति के लोगों का उत्तर इसके सिवा कुछ न था कि उन्होंने कहा : लूत के घरवालों को अपनी बस्ती से निकाल दो। निःसंदेह ये ऐसे लोग हैं जो बड़े पाक-साफ़ बनते हैं।"},{"a":57,"ar":"فَأَنجَيْنَـٰهُ وَأَهْلَهُۥٓ إِلَّا ٱمْرَأَتَهُۥ قَدَّرْنَـٰهَا مِنَ ٱلْغَـٰبِرِينَ","en":"So We saved him and his family, except for his wife; We destined her to be of those who remained behind.","ur":"تو ہم نے ان کو اور ان کے گھر والوں کو نجات دی۔ مگر ان کی بیوی کہ اس کی نسبت ہم نے مقرر کر رکھا ہے (کہ وہ پیچھے رہنے والوں میں ہوگی)","hi":"तो हमने उसे तथा उसके घरवालों को बचा लिया, सिवाय उसकी बीवी के। हमने उसे पीछे रह जाने वालों में तय कर दिया था।"},{"a":58,"ar":"وَأَمْطَرْنَا عَلَيْهِم مَّطَرًا ۖ فَسَآءَ مَطَرُ ٱلْمُنذَرِينَ","en":"And We rained upon them a rain [of stones], and evil was the rain of those who were warned.","ur":"اور ہم نے ان پر مینھہ برسایا سو (جو) مینھہ ان لوگوں پر برسا جن کو متنبہ کردیا گیا تھا، برا تھا","hi":"और हमने उनपर भारी वर्षा बरसाई। तो बुरी बारिश थी उन लोगों के लिए जो डराए गए थे।"},{"a":59,"ar":"قُلِ ٱلْحَمْدُ لِلَّهِ وَسَلَـٰمٌ عَلَىٰ عِبَادِهِ ٱلَّذِينَ ٱصْطَفَىٰٓ ۗ ءَآللَّهُ خَيْرٌ أَمَّا يُشْرِكُونَ","en":"Say, [O Muḥammad], \"Praise be to Allāh, and peace upon His servants whom He has chosen. Is Allāh better or what they associate with Him?\"","ur":"کہہ دو کہ سب تعریف خدا ہی کو سزاوار ہے اور اس کے بندوں پر سلام ہے جن کو اس نے منتخب فرمایا۔ بھلا خدا بہتر ہے یا وہ جن کو یہ (اس کا شریک) ٹھہراتے ہیں","hi":"आप कह दें: सब प्रशंसा अल्लाह के लिए है और सलाम है उसके उन बंदों पर, जिन्हें उसने चुन लिया। क्या अल्लाह बेहतर है, या वे जिन्हें ये साझी ठहराते हैं?"},{"a":60,"ar":"أَمَّنْ خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَأَنزَلَ لَكُم مِّنَ ٱلسَّمَآءِ مَآءً فَأَنۢبَتْنَا بِهِۦ حَدَآئِقَ ذَاتَ بَهْجَةٍ مَّا كَانَ لَكُمْ أَن تُنۢبِتُوا۟ شَجَرَهَآ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ بَلْ هُمْ قَوْمٌ يَعْدِلُونَ","en":"[More precisely], is He [not best] who created the heavens and the earth and sent down for you rain from the sky, causing to grow thereby gardens of joyful beauty which you could not [otherwise] have grown the trees thereof? Is there a deity with Allāh? [No], but they are a people who ascribe equals [to Him].","ur":"بھلا کس نے آسمانوں اور زمین کو پیدا کیا اور (کس نے) تمہارے لئے آسمان سے پانی برسایا۔ (ہم نے) پھر ہم ہی نے اس سے سرسبز باغ اُگائے۔ تمہارا کام تو نہ تھا کہ تم اُن کے درختوں کو اگاتے۔ تو کیا خدا کے ساتھ کوئی اور بھی معبود ہے؟ (ہرگز نہیں) بلکہ یہ لوگ رستے سے الگ ہو رہے ہیں","hi":"(क्या वे साझीदार बेहतर हैं) या वह जिसने आकाशों और धरती को पैदा किया और आकाश से तुम्हारे लिए पानी उतारा, फिर हमने उसके साथ शानदार बाग़ लगाए। तुम्हारे बस में नहीं था कि उनके वृक्ष उगाते। क्या अल्लाह के साथ कोई (अन्य) पूज्य है? बल्कि ये ऐसे लोग हैं जो रास्ते से हट रहे हैं।"},{"a":61,"ar":"أَمَّن جَعَلَ ٱلْأَرْضَ قَرَارًا وَجَعَلَ خِلَـٰلَهَآ أَنْهَـٰرًا وَجَعَلَ لَهَا رَوَٰسِىَ وَجَعَلَ بَيْنَ ٱلْبَحْرَيْنِ حَاجِزًا ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ بَلْ أَكْثَرُهُمْ لَا يَعْلَمُونَ","en":"Is He [not best] who made the earth a stable ground and placed within it rivers and made for it firmly set mountains and placed between the two seas a barrier? Is there a deity with Allāh? [No], but most of them do not know.","ur":"بھلا کس نے زمین کو قرار گاہ بنایا اور اس کے بیچ نہریں بنائیں اور اس کے لئے پہاڑ بنائے اور (کس نے) دو دریاؤں کے بیچ اوٹ بنائی (یہ سب کچھ خدا نے بنایا) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے؟ (ہرگز نہیں) بلکہ ان میں اکثر دانش نہیں رکھتے","hi":"(क्या वे साझीदार बेहतर हैं) या वह जिसने धरती को ठहरने का स्थान बनाया और उसके बीच नहरें बनाईं और उसके लिए पहाड़ बनाए और दो समुद्रों के बीच अवरोध बनाया? क्या अल्लाह के साथ कोई (अन्य) पूज्य है ? बल्कि उनमें से अधिकतर लोग नहीं जानते।"},{"a":62,"ar":"أَمَّن يُجِيبُ ٱلْمُضْطَرَّ إِذَا دَعَاهُ وَيَكْشِفُ ٱلسُّوٓءَ وَيَجْعَلُكُمْ خُلَفَآءَ ٱلْأَرْضِ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ قَلِيلًا مَّا تَذَكَّرُونَ","en":"Is He [not best] who responds to the desperate one when he calls upon Him and removes evil and makes you inheritors of the earth? Is there a deity with Allāh? Little do you remember.","ur":"بھلا کون بیقرار کی التجا قبول کرتا ہے۔ جب وہ اس سے دعا کرتا ہے اور (کون اس کی) تکلیف کو دور کرتا ہے اور (کون) تم کو زمین میں (اگلوں کا) جانشین بناتا ہے (یہ سب کچھ خدا کرتا ہے) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے (ہرگز نہیں مگر) تم بہت کم غور کرتے ہو","hi":"या वह जो व्याकुल की प्रार्थना स्वीकार करता है, जब वह उसे पुकारता है और दुखों को दूर करता है और तुम्हें धरती का उत्तराधिकारी बनाता है? क्या अल्लाह के साथ कोई (अन्य) पूज्य है? तुम बहुत कम उपदेश ग्रहण करते हो।"},{"a":63,"ar":"أَمَّن يَهْدِيكُمْ فِى ظُلُمَـٰتِ ٱلْبَرِّ وَٱلْبَحْرِ وَمَن يُرْسِلُ ٱلرِّيَـٰحَ بُشْرًۢا بَيْنَ يَدَىْ رَحْمَتِهِۦٓ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ تَعَـٰلَى ٱللَّهُ عَمَّا يُشْرِكُونَ","en":"Is He [not best] who guides you through the darknesses of the land and sea and who sends the winds as good tidings before His mercy? Is there a deity with Allāh? High is Allāh above whatever they associate with Him.","ur":"بھلا کون تم کو جنگل اور دریا کے اندھیروں میں رستہ بناتا ہے اور (کون) ہواؤں کو اپنی رحمت کے آگے خوشخبری بناکر بھیجتا ہے (یہ سب کچھ خدا کرتا ہے) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے؟ (ہرگز نہیں)۔ یہ لوگ جو شرک کرتے ہیں خدا (کی شان) اس سے بلند ہے","hi":"या वह जो थल और समुद्र के अँधेरों में तुम्हारा मार्गदर्शन करता है तथा वह जो हवाओं को अपनी दया (वर्षा) से पहले शुभ-सूचना देने के लिए भेजता है? क्या अल्लाह के साथ कोई (और) पूज्य है? बहुत उच्च है अल्लाह उससे जो वे साझी ठहराते हैं।"},{"a":64,"ar":"أَمَّن يَبْدَؤُا۟ ٱلْخَلْقَ ثُمَّ يُعِيدُهُۥ وَمَن يَرْزُقُكُم مِّنَ ٱلسَّمَآءِ وَٱلْأَرْضِ ۗ أَءِلَـٰهٌ مَّعَ ٱللَّهِ ۚ قُلْ هَاتُوا۟ بُرْهَـٰنَكُمْ إِن كُنتُمْ صَـٰدِقِينَ","en":"Is He [not best] who begins creation and then repeats it and who provides for you from the heaven and earth? Is there a deity with Allāh? Say, \"Produce your proof, if you should be truthful.\"","ur":"بھلا کون خلقت کو پہلی بار پیدا کرتا۔ پھر اس کو بار بار پیدا کرتا رہتا ہے اور (کون) تم کو آسمان اور زمین سے رزق دیتا ہے (یہ سب کچھ خدا کرتا ہے) تو کیا خدا کے ساتھ کوئی اور معبود بھی ہے (ہرگز نہیں) کہہ دو کہ (مشرکو) اگر تم سچے ہو تو دلیل پیش کرو","hi":"या वह जो सृष्टि का आरंभ करता है, फिर उसे दोहराता है, और जो तुम्हें आकाश और धरती से जीविका देता है? क्या अल्लाह के साथ कोई (और) पूज्य है? कह दीजिए : लाओ अपना प्रमाण, यदि तुम सच्चे हो।"},{"a":65,"ar":"قُل لَّا يَعْلَمُ مَن فِى ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ٱلْغَيْبَ إِلَّا ٱللَّهُ ۚ وَمَا يَشْعُرُونَ أَيَّانَ يُبْعَثُونَ","en":"Say, \"None in the heavens and earth knows the unseen except Allāh, and they do not perceive when they will be resurrected.\"","ur":"کہہ دو کہ جو لوگ آسمانوں اور زمین میں ہیں خدا کے سوا غیب کی باتیں نہیں جانتے۔ اور نہ یہ جانتے ہیں کہ کب (زندہ کرکے) اٹھائے جائیں گے","hi":"आप कह दें : अल्लाह के सिवा, आकाशों और धरती में जो भी है, ग़ैब (परोक्ष की बात) नहीं जानता और वे नहीं जानते कि वे कब उठाये जाएँगे।"},{"a":66,"ar":"بَلِ ٱدَّٰرَكَ عِلْمُهُمْ فِى ٱلْـَٔاخِرَةِ ۚ بَلْ هُمْ فِى شَكٍّ مِّنْهَا ۖ بَلْ هُم مِّنْهَا عَمُونَ","en":"Rather, their knowledge is arrested concerning the Hereafter. Rather, they are in doubt about it. Rather, they are, concerning it, blind.","ur":"بلکہ آخرت (کے بارے) میں ان کا علم منتہی ہوچکا ہے بلکہ وہ اس سے شک میں ہیں۔ بلکہ اس سے اندھے ہو رہے ہیں","hi":"बल्कि आख़िरत (परलोक) के विषय में उनका ज्ञान समाप्त हो गया है। बल्कि वे उसके बारे में संदेह में हैं। बल्कि वे उससे अंधे हैं।"},{"a":67,"ar":"وَقَالَ ٱلَّذِينَ كَفَرُوٓا۟ أَءِذَا كُنَّا تُرَٰبًا وَءَابَآؤُنَآ أَئِنَّا لَمُخْرَجُونَ","en":"And those who disbelieve say, \"When we have become dust as well as our forefathers, will we indeed be brought out [of the graves]?","ur":"اور جو لوگ کافر ہیں کہتے ہیں جب ہم اور ہمارے باپ دادا مٹی ہو جائیں گے تو کیا ہم پھر (قبروں سے) نکالے جائیں گے","hi":"और उन लोगों ने कहा जिन्होंने कुफ़्र किया : क्या जब हम मिट्टी हो जाएँगे और हमारे बाप-दादा भी, तो क्या सचमुच हम अवश्य निकाले जाने वाले हैं?"},{"a":68,"ar":"لَقَدْ وُعِدْنَا هَـٰذَا نَحْنُ وَءَابَآؤُنَا مِن قَبْلُ إِنْ هَـٰذَآ إِلَّآ أَسَـٰطِيرُ ٱلْأَوَّلِينَ","en":"We have been promised this, we and our forefathers, before. This is not but legends of the former peoples.\"","ur":"یہ وعدہ ہم سے اور ہمارے باپ دادا سے پہلے سے ہوتا چلا آیا ہے (کہاں کا اُٹھنا اور کیسی قیامت) یہ تو صرف پہلے لوگوں کی کہانیاں ہیں","hi":"निश्चय इससे पहले हमसे यह वादा किया गया और हमारे बाप-दादा से भी, ये तो बस पहले लोगों की काल्पनिक कहानियाँ हैं।"},{"a":69,"ar":"قُلْ سِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُجْرِمِينَ","en":"Say, [O Muḥammad], \"Proceed [i.e., travel] through the land and observe how was the end of the criminals.\"","ur":"کہہ دو کہ ملک میں چلو پھرو پھر دیکھو کہ گنہگاروں کا انجام کیا ہوا ہے","hi":"कह दीजिए : धरती में चलो-फिरो, फिर देखो अपराधियों का परिणाम कैसा हुआ!"},{"a":70,"ar":"وَلَا تَحْزَنْ عَلَيْهِمْ وَلَا تَكُن فِى ضَيْقٍ مِّمَّا يَمْكُرُونَ","en":"And grieve not over them or be in distress from what they conspire.","ur":"اور ان (کے حال) پر غم نہ کرنا اور نہ اُن چالوں سے جو یہ کر رہے ہیں تنگ دل ہونا","hi":"और आप उनपर शोक न करें और न उससे किसी संकीर्णता में हों, जो वे चाल चलते हैं।"},{"a":71,"ar":"وَيَقُولُونَ مَتَىٰ هَـٰذَا ٱلْوَعْدُ إِن كُنتُمْ صَـٰدِقِينَ","en":"And they say, \"When is [the fulfillment of] this promise, if you should be truthful?\"","ur":"اور کہتے ہیں کہ اگر تم سچے ہو تو یہ وعدہ کب پورا ہوگا؟","hi":"तथा वे कहते हैं : कब पूरा होगा यह वादा, यदि तुम सच्चे हो?"},{"a":72,"ar":"قُلْ عَسَىٰٓ أَن يَكُونَ رَدِفَ لَكُم بَعْضُ ٱلَّذِى تَسْتَعْجِلُونَ","en":"Say, \"Perhaps it is close behind you [i.e., very near] - some of that for which you are impatient.","ur":"کہہ دو کہ جس (عذاب) کے لئے تم جلدی کر رہے ہو شاید اس میں سے کچھ تمہارے نزدیک آپہنچا ہو","hi":"आप कह दें : क़रीब है कि उसका कुछ भाग तुम्हारे पीछे आ पहुँचा हो, जो तुम जल्दी माँग रहे हो।"},{"a":73,"ar":"وَإِنَّ رَبَّكَ لَذُو فَضْلٍ عَلَى ٱلنَّاسِ وَلَـٰكِنَّ أَكْثَرَهُمْ لَا يَشْكُرُونَ","en":"And indeed, your Lord is the possessor of bounty for the people, but most of them are not grateful.\"","ur":"اور تمہارا پروردگار تو لوگوں پر فضل کرنے والا ہے لیکن ان میں سے اکثر شکر نہیں کرتے","hi":"तथा निःसंदेह आपका पालनहार निश्चय लोगों पर बड़ा अनुग्रह करने वाला है। किंतु उनमें से अधिकतर लोग शुक्र नहीं करते।"},{"a":74,"ar":"وَإِنَّ رَبَّكَ لَيَعْلَمُ مَا تُكِنُّ صُدُورُهُمْ وَمَا يُعْلِنُونَ","en":"And indeed, your Lord knows what their breasts conceal and what they declare.","ur":"اور جو باتیں ان کے سینوں میں پوشیدہ ہوتی ہیں اور جو کام وہ ظاہر کرتے ہیں تمہارا پروردگار ان (سب) کو جانتا ہے","hi":"और निःसंदेह आपका पालनहार निश्चय जानता है जो कुछ उनके सीने छिपाते हैं और जो कुछ वे प्रकट करते हैं।"},{"a":75,"ar":"وَمَا مِنْ غَآئِبَةٍ فِى ٱلسَّمَآءِ وَٱلْأَرْضِ إِلَّا فِى كِتَـٰبٍ مُّبِينٍ","en":"And there is nothing concealed within the heaven and the earth except that it is in a clear Register.","ur":"اور آسمانوں اور زمین میں کوئی پوشیدہ چیز نہیں ہے مگر (وہ) کتاب روشن میں (لکھی ہوئی) ہے","hi":"और आकाश तथा धरती में कोई छिपी चीज़ नहीं, परंतु वह एक स्पष्ट किताब में मौजूद है।"},{"a":76,"ar":"إِنَّ هَـٰذَا ٱلْقُرْءَانَ يَقُصُّ عَلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَكْثَرَ ٱلَّذِى هُمْ فِيهِ يَخْتَلِفُونَ","en":"Indeed, this Qur’ān relates to the Children of Israel most of that over which they disagree.","ur":"بےشک یہ قرآن بنی اسرائیل کے سامنے اکثر باتیں جن میں وہ اختلاف کرتے ہیں، بیان کر دیتا ہے","hi":"निःसंदेह यह क़ुरआन इसराईल की संतान के सामने अधिकतर वे बातें वर्णन करता है, जिनमें वे मतभेद करते हैं।"},{"a":77,"ar":"وَإِنَّهُۥ لَهُدًى وَرَحْمَةٌ لِّلْمُؤْمِنِينَ","en":"And indeed, it is guidance and mercy for the believers.","ur":"اور بےشک یہ مومنوں کے لئے ہدایات اور رحمت ہے","hi":"और निःसंदेह वह निश्चय ईमान वालों के लिए सर्वथा मार्गदर्शन तथा दया है।"},{"a":78,"ar":"إِنَّ رَبَّكَ يَقْضِى بَيْنَهُم بِحُكْمِهِۦ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْعَلِيمُ","en":"Indeed, your Lord will judge between them by His [wise] judgement. And He is the Exalted in Might, the Knowing.","ur":"تمہارا پروردگار (قیامت کے روز) اُن میں اپنے حکم سے فیصلہ کر دے گا اور وہ غالب (اور) علم والا ہے","hi":"निःसंदेह आपका पालनहार उनके बीच अपने आदेश से निर्णय कर देगा तथा वही सब पर प्रभुत्वशाली, सब कुछ जानने वाला है।"},{"a":79,"ar":"فَتَوَكَّلْ عَلَى ٱللَّهِ ۖ إِنَّكَ عَلَى ٱلْحَقِّ ٱلْمُبِينِ","en":"So rely upon Allāh; indeed, you are upon the clear truth.","ur":"تو خدا پر بھروسہ رکھو تم تو حق صریح پر ہو","hi":"अतः आप अल्लाह पर भरोसा करें। निश्चय आप स्पष्ट सत्य पर हैं।"},{"a":80,"ar":"إِنَّكَ لَا تُسْمِعُ ٱلْمَوْتَىٰ وَلَا تُسْمِعُ ٱلصُّمَّ ٱلدُّعَآءَ إِذَا وَلَّوْا۟ مُدْبِرِينَ","en":"Indeed, you will not make the dead hear, nor will you make the deaf hear the call when they have turned their backs retreating.","ur":"کچھ شک نہیں کہ تم مردوں کو (بات) نہیں سنا سکتے اور نہ بہروں کو جب کہ وہ پیٹھ پھیر کر پھر جائیں آواز سنا سکتے ہو","hi":"निःसंदेह आप मुर्दों को नहीं सुना सकते और न बहरों को अपनी पुकार सुना सकते, जब वे पीठ फेरकर पलट जाएँ।"},{"a":81,"ar":"وَمَآ أَنتَ بِهَـٰدِى ٱلْعُمْىِ عَن ضَلَـٰلَتِهِمْ ۖ إِن تُسْمِعُ إِلَّا مَن يُؤْمِنُ بِـَٔايَـٰتِنَا فَهُم مُّسْلِمُونَ","en":"And you cannot guide the blind away from their error. You will only make hear those who believe in Our verses so they are Muslims [i.e., submitting to Allāh].","ur":"اور نہ اندھوں کو گمراہی سے (نکال کر) رستہ دیکھا سکتے ہو۔ تم ان ہی کو سنا سکتے ہو جو ہماری آیتوں پر ایمان لاتے ہیں اور وہ فرمانبردار ہو جاتے ہیں","hi":"तथा न आप कभी अंधों को उनकी गुमारही से हटाकर सीधे मार्ग पर लाने वाले हैं। आप तो बस उन्हीं को सुना सकते हैं, जो हमारी आयतों पर ईमान रखते हैं। सो वही आज्ञाकारी हैं।"},{"a":82,"ar":"۞ وَإِذَا وَقَعَ ٱلْقَوْلُ عَلَيْهِمْ أَخْرَجْنَا لَهُمْ دَآبَّةً مِّنَ ٱلْأَرْضِ تُكَلِّمُهُمْ أَنَّ ٱلنَّاسَ كَانُوا۟ بِـَٔايَـٰتِنَا لَا يُوقِنُونَ","en":"And when the word [i.e., decree] befalls them, We will bring forth for them a creature from the earth speaking to them, [saying] that the people were, of Our verses, not certain [in faith].","ur":"اور جب اُن کے بارے میں (عذاب) کا وعدہ پورا ہوگا تو ہم اُن کے لئے زمین میں سے ایک جانور نکالیں گے جو ان سے بیان کر دے گا۔ اس لئے کہ لوگ ہماری آیتوں پر ایمان نہیں لاتے تھے","hi":"और जब उनपर बात पूरी हो जाएगी, तो हम उनके लिए धरती से एक पशु निकालेंगे, जो उनसे बात करेगा कि निश्चय लोग हमारी आयतों पर विश्वास नहीं करते थे।"},{"a":83,"ar":"وَيَوْمَ نَحْشُرُ مِن كُلِّ أُمَّةٍ فَوْجًا مِّمَّن يُكَذِّبُ بِـَٔايَـٰتِنَا فَهُمْ يُوزَعُونَ","en":"And [warn of] the Day when We will gather from every nation a company of those who deny Our signs, and they will be [driven] in rows","ur":"اور جس روز ہم ہر اُمت میں سے اس گروہ کو جمع کریں گے جو ہماری آیتوں کی تکذیب کرتے تھے تو اُن کی جماعت بندی کی جائے گی","hi":"तथा जिस दिन हम प्रत्येक समुदाय में से उन लोगों का एक गिरोह एकत्र करेंगे, जो हमारी आयतों को झुठलाया करते थे, फिर उन्हें श्रेणियों में बांटा जाएगा।"},{"a":84,"ar":"حَتَّىٰٓ إِذَا جَآءُو قَالَ أَكَذَّبْتُم بِـَٔايَـٰتِى وَلَمْ تُحِيطُوا۟ بِهَا عِلْمًا أَمَّاذَا كُنتُمْ تَعْمَلُونَ","en":"Until, when they arrive [at the place of Judgement], He will say, \"Did you deny My signs while you encompassed them not in knowledge, or what [was it that] you were doing?\"","ur":"یہاں تک کہ جب (سب) آجائیں گے تو (خدا) فرمائے گا کہ کیا تم نے میری آیتوں کو جھٹلا دیا تھا اور تم نے (اپنے) علم سے ان پر احاطہ تو کیا ہی نہ تھا۔ بھلا تم کیا کرتے تھے","hi":"यहाँ तक कि जब वे आ जाएँगे, तो (अल्लाह) फरमाएगा : क्या तुमने मेरी आयतों को झुठला दिया, हालाँकि तुमने उनका पूर्ण ज्ञान प्राप्त नहीं किया था, या क्या था जो तुम किया करते थे?"},{"a":85,"ar":"وَوَقَعَ ٱلْقَوْلُ عَلَيْهِم بِمَا ظَلَمُوا۟ فَهُمْ لَا يَنطِقُونَ","en":"And the decree will befall them for the wrong they did, and they will not [be able to] speak.","ur":"اور اُن کے ظلم کے سبب اُن کے حق میں وعدہ (عذاب) پورا ہوکر رہے گا تو وہ بول بھی نہ سکیں گے","hi":"और उनपर (यातना की) बात सिद्ध हो जाएगी, उसके बदले जो उन्होंने अत्याचार किया, सो वे बोल न सकेंगे।"},{"a":86,"ar":"أَلَمْ يَرَوْا۟ أَنَّا جَعَلْنَا ٱلَّيْلَ لِيَسْكُنُوا۟ فِيهِ وَٱلنَّهَارَ مُبْصِرًا ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَـٰتٍ لِّقَوْمٍ يُؤْمِنُونَ","en":"Do they not see that We made the night that they may rest therein and the day giving sight? Indeed in that are signs for a people who believe.","ur":"کیا اُنہوں نے نہیں دیکھا کہ ہم نے رات کو (اس لئے) بنایا ہے کہ اس میں آرام کریں اور دن کو روشن (بنایا ہے کہ اس میں کام کریں) بےشک اس میں مومن لوگوں کے لئے نشانیاں ہیں","hi":"क्या उन्होंने नहीं देखा कि हमने रात बनाई, ताकि वे उसमें आराम करें तथा दिन को प्रकाशमान (बनाया)। निःसंदेह इसमें उन लोगों के लिए बहुत-सी निशानियाँ हैं, जो ईमान लाते हैं।"},{"a":87,"ar":"وَيَوْمَ يُنفَخُ فِى ٱلصُّورِ فَفَزِعَ مَن فِى ٱلسَّمَـٰوَٰتِ وَمَن فِى ٱلْأَرْضِ إِلَّا مَن شَآءَ ٱللَّهُ ۚ وَكُلٌّ أَتَوْهُ دَٰخِرِينَ","en":"And [warn of] the Day the Horn will be blown, and whoever is in the heavens and whoever is on the earth will be terrified except whom Allāh wills. And all will come to Him humbled.","ur":"اور جس روز صور پھونکا جائے گا تو جو لوگ آسمانوں اور زمین میں ہیں سب گھبرا اُٹھیں گے مگر وہ جسے خدا چاہے اور سب اس کے پاس عاجز ہو کر چلے آئیں گے","hi":"और जिस दिन सूर (नरसिंघा) में फूँका जाएगा, तो जो भी आकाशों में है और जो भी धरती में है, घबरा जाएगा, सिवाय उसके जिसे अल्लाह चाहे। तथा वे सब उसके पास अपमानित होकर आएँगे।"},{"a":88,"ar":"وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ ۚ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ ۚ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ","en":"And you see the mountains, thinking them motionless, while they will pass as the passing of clouds. [It is] the work of Allāh, who perfected all things. Indeed, He is Aware of that which you do.","ur":"اور تم پہاڑوں کو دیکھتے ہو تو خیال کرتے ہو کہ (اپنی جگہ پر) کھڑے ہیں مگر وہ (اس روز) اس طرح اُڑے پھریں گے جیسے بادل۔ (یہ) خدا کی کاریگری ہے جس نے ہر چیز کو مضبوط بنایا۔ بےشک وہ تمہارے سب افعال سے باخبر ہے","hi":"और तुम पर्वतों को देखोगे, उन्हें समझोगे कि वे जमे हुए हैं, हालाँकि वे बादलों के चलने की तरह चल रहे होंगे, उस अल्लाह की कारीगरी से जिसने हर चीज़ को मज़बूत बनाया। निःसंदेह वह उससे भली-भाँति सूचित है जो तुम करते हो।"},{"a":89,"ar":"مَن جَآءَ بِٱلْحَسَنَةِ فَلَهُۥ خَيْرٌ مِّنْهَا وَهُم مِّن فَزَعٍ يَوْمَئِذٍ ءَامِنُونَ","en":"Whoever comes [at Judgement] with a good deed will have better than it, and they, from the terror of that Day, will be safe.","ur":"جو شخص نیکی لےکر آئے گا تو اس کے لئے اس سے بہتر (بدلہ تیار) ہے اور ایسے لوگ (اُس روز) گھبراہٹ سے بےخوف ہوں گے","hi":"जो व्यक्ति नेकी लेकर आएगा, तो उसके लिए उससे उत्तम प्रतिफल है और ये लोग उस दिन के भय से सुरक्षित होंगे।"},{"a":90,"ar":"وَمَن جَآءَ بِٱلسَّيِّئَةِ فَكُبَّتْ وُجُوهُهُمْ فِى ٱلنَّارِ هَلْ تُجْزَوْنَ إِلَّا مَا كُنتُمْ تَعْمَلُونَ","en":"And whoever comes with an evil deed - their faces will be overturned into the Fire, [and it will be said], \"Are you recompensed except for what you used to do?\"","ur":"اور جو برائی لے کر آئے گا تو ایسے لوگ اوندھے منہ دوزخ میں ڈال دیئے جائیں گے۔ تم کو تو اُن ہی اعمال کا بدلہ ملے گا جو تم کرتے رہے ہو","hi":"और जो बुराई लेकर आएगा, तो उनके चेहरे आग में औंधे डाले जाएँगे। तुम उसी का बदला दिए जाओगे, जो तुम किया करते थे।"},{"a":91,"ar":"إِنَّمَآ أُمِرْتُ أَنْ أَعْبُدَ رَبَّ هَـٰذِهِ ٱلْبَلْدَةِ ٱلَّذِى حَرَّمَهَا وَلَهُۥ كُلُّ شَىْءٍ ۖ وَأُمِرْتُ أَنْ أَكُونَ مِنَ ٱلْمُسْلِمِينَ","en":"[Say, O Muḥammad], \"I have only been commanded to worship the Lord of this city, who made it sacred and to whom [belongs] all things. And I am commanded to be of the Muslims [i.e., those who submit to Allāh].","ur":"(کہہ دو) کہ مجھ کو یہی ارشاد ہوا ہے کہ اس شہر (مکہ) کے مالک کی عبادت کروں جس نے اس کو محترم (اور مقام ادب) بنایا ہے اور سب چیز اُسی کی ہے اور یہ بھی حکم ہوا ہے کہ اس کا حکم بردار رہوں","hi":"मुझे तो बस यही आदेश दिया गया है कि मैं इस नगर (मक्का) के पालनहार की इबादत करूँ, जिसने इसे पवित्र (सम्मानित) बनाया है तथा उसी के लिए हर चीज़ है और मुझे आदेश दिया गया है कि मैं आज्ञाकारियों में से हो जाऊँ।"},{"a":92,"ar":"وَأَنْ أَتْلُوَا۟ ٱلْقُرْءَانَ ۖ فَمَنِ ٱهْتَدَىٰ فَإِنَّمَا يَهْتَدِى لِنَفْسِهِۦ ۖ وَمَن ضَلَّ فَقُلْ إِنَّمَآ أَنَا۠ مِنَ ٱلْمُنذِرِينَ","en":"And to recite the Qur’ān.\" And whoever is guided is only guided for [the benefit of] himself; and whoever strays - say, \"I am only [one] of the warners.\"","ur":"اور یہ بھی کہ قرآن پڑھا کروں۔ تو جو شخص راہ راست اختیار کرتا ہے تو اپنے ہی فائدے کے لئے اختیار کرتا ہے۔ اور جو گمراہ رہتا ہے تو کہہ دو کہ میں تو صرف نصیحت کرنے والا ہوں","hi":"तथा यह कि मैं क़ुरआन पढ़कर सुनाऊँ। फिर जो सीधी राह पर आया, वह अपने ही लिए राह पर आता है और जो गुमराह हुआ, तो आप कह दें कि मैं तो बस डराने वालों में से हूँ।"},{"a":93,"ar":"وَقُلِ ٱلْحَمْدُ لِلَّهِ سَيُرِيكُمْ ءَايَـٰتِهِۦ فَتَعْرِفُونَهَا ۚ وَمَا رَبُّكَ بِغَـٰفِلٍ عَمَّا تَعْمَلُونَ","en":"And say, \"[All] praise is [due] to Allāh. He will show you His signs, and you will recognize them. And your Lord is not unaware of what you do.\"","ur":"اور کہو کہ خدا کا شکر ہے۔ وہ تم کو عنقریب اپنی نشانیاں دکھائے گا تو تم اُن کو پہچان لو گے۔ اور جو کام تم کرتے ہو تمہارا پروردگار اُن سے بےخبر نہیں ہے","hi":"तथा आप कह दें : सब प्रशंसा अल्लाह के लिए है। वह जल्द ही तुम्हें अपनी निशानियाँ दिखाएगा, तो तुम उन्हें पहचान लोगे और तुम्हारा पालनहार उससे बेखबर नहीं है, जो कुछ तुम करते हो।"}],"tlx":{"hi":"अन-नम्ल","ur":"النمل"}};
